#![allow(unused)]
use verus::prelude::*;

verus! {

    /// Given two vectors `a` and `b` of i8s of the same length,
    /// produce a `Vec<bool>` `result` so that for every valid index `i`,
    /// `result[i]` is `true` if and only if `a[i] != b[i]`.
    fn not_equal(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
        requires
            a.len() == b.len(),
        ensures
            result.len() == a.len(),
        ensures
            forall |i: usize| i < a.len() ==> result[i] == (a[i] != b[i])
    {
        let mut res: Vec<bool> = Vec::new();
        let len = a.len();
        let mut i: usize = 0;
        while i < len
            invariant
                i <= len,
            invariant
                res.len() == i,
            invariant
                forall |j: usize| j < i ==> res[j] == (a[j] != b[j]),
            decreases
                len - i
        {
            let ai = a[i];
            let bi = b[i];
            let neq = ai != bi;
            res.push(neq);
            i += 1;
        }
        // Return the fully constructed vector
        result = res;
    }
}